(function(root){
'use strict';
const q=(id,prompt,options,correct,explanation,graph)=>({id,prompt,options:options.map(([id,label])=>({id,label})),correct:[correct],explanation,graph});
const plot=(fn,extra={})=>({type:'plot',fn,...extra});
const table=(headers,rows,caption)=>({type:'table',headers,rows,caption});
const LESSONS=[
 {id:'functions',short:'Functions & domains',title:'Which inputs are allowed?',goal:'Read a function as an input-output rule and preserve domain restrictions.',
  controls:[{name:'kind',label:'Function family',options:[['sqrt','f(x) = √(x − k)'],['reciprocal','f(x) = 1/(x − k)']]},{name:'k',label:'Shift k',min:-3,max:3,step:1},{name:'x',label:'Input x',min:-4,max:6,step:.5}],defaults:{kind:'sqrt',k:1,x:2},motion:{key:'x',end:6,replay:-4},
  steps:[
   {title:'One input has one output.',text:'A function assigns exactly one output to each input in its domain. The same output may come from several inputs: x² gives 4 for both 2 and −2. That is still a function. A graph with two different y-values at one x is not a function of x.',try:'Choose an input and describe its output, including the case where it is undefined.'},
   {title:'Restrictions come from the rule.',text:'For real outputs, √(x − k) needs x − k ≥ 0, so x ≥ k. The reciprocal 1/(x − k) instead needs x ≠ k. A square-root boundary may be included; a zero denominator is excluded.',try:'Set k = 1 and compare the two rules at x = 1 and x = 0.'},
   {title:'Composition has an order.',text:'If f(x) = 2x + 1 and g(x) = x², f(g(2)) = f(4) = 9, while g(f(2)) = g(5) = 25. The inside rule acts first. Its output must be an allowed input to the outside rule.',try:'Explain the difference between the two compositions using the intermediate value.'},
   {title:'An inverse needs unique recovery.',text:'An inverse function recovers the original input. The function x² on all real inputs is not one-to-one, so it has no inverse function on that domain. Restricting x to x ≥ 0 allows the inverse √x. Keep restrictions visible when reversing or simplifying a rule.',try:'Explain why an output of 4 does not identify a unique input for unrestricted x².'}
  ],
  predict:q('af-p1','For real-valued f(x) = √(x − 2), which inputs are allowed?',[['ge','x ≥ 2'],['gt','x > 2'],['all','All real x']],'ge','The radicand must be nonnegative. x = 2 gives √0 = 0, so the boundary is included.',plot('sqrt',{k:2})),
  checks:[q('af-c1','For f(x) = 1/(x + 3), which input is excluded?',[['minus','−3'],['plus','3'],['none','No input is excluded.']],'minus','At x = −3 the denominator is zero. All other real inputs are allowed.',plot('reciprocal',{k:-3})),q('af-c2','Let f(x) = 3x − 1 and g(x) = x². What is f(g(2))?',[['11','11'],['25','25'],['5','5']],'11','First g(2) = 4, then f(4) = 12 − 1 = 11. Reversing the order would give 25.',table(['Rule','Expression'],[['f(x)','3x − 1'],['g(x)','x²']],'Apply the inside function first.'))],next:'Check domains of new radical and rational rules, then track the intermediate value in a composition.'},
 {id:'transformations',short:'Graphs & transformations',title:'What moves, and what changes shape?',goal:'Connect f(x − h) and vertical transformations to features of a graph.',
  controls:[{name:'a',label:'Vertical multiplier a',options:[[-2,'−2: reflect and stretch'],[-1,'−1: reflect'],[1,'1: original scale'],[2,'2: stretch']],numeric:true},{name:'h',label:'Horizontal shift h',min:-3,max:3,step:.5},{name:'k',label:'Vertical shift k',min:-3,max:3,step:.5}],defaults:{a:1,h:1,k:0},motion:{key:'h',end:3,replay:-3},
  steps:[
   {title:'Use a known parent function.',text:'The parent f(x) = x² has vertex (0, 0), is symmetric about x = 0, and increases away from its minimum. Matching a formula to these features is more informative than plotting a few unrelated points.',try:'Set a = 1, h = 0, k = 0. Locate the parent vertex.'},
   {title:'A horizontal change is inside the rule.',text:'For y = (x − h)², the squared input becomes zero at x = h. A positive h shifts the vertex to the right. The minus sign is explained by solving x − h = 0; it is not a rule to guess from the sign alone.',try:'Move h to 2 and explain why the vertex is at x = 2.'},
   {title:'Vertical changes are outside.',text:'For y = a(x − h)² + k, k raises or lowers every output. The magnitude |a| stretches or compresses vertical distances from y = k; a negative a reflects the graph across that horizontal line. The vertex remains (h, k) when a ≠ 0.',try:'Hold h and k fixed while switching a from 1 to −2.'},
   {title:'Features support equations and inequalities.',text:'Zeros occur where y = 0. For (x − 1)² − 4, the vertex is (1, −4), and zeros are x = −1 and x = 3. Between them the graph is below the axis. A graph suggests these features; substitution and algebra check the exact values.',try:'Set h = 1 and k = −3. Predict the direction of the change before moving k again.'}
  ],
  predict:q('af-p2','What is the vertex of y = (x − 2)² + 1?',[['right','(2, 1)'],['left','(−2, 1)'],['swap','(1, 2)']],'right','The squared part is smallest at x = 2, where y = 1.',plot('square',{a:1,h:2,k:1})),
  checks:[q('af-c3','Compared with y = x², what happens in y = −2(x + 1)² + 3?',[['correct','Left 1, up 3, reflected, and vertically stretched by 2.'],['right','Right 1, up 3, with no reflection.'],['down','Left 1, down 3, and compressed by 2.']],'correct','x + 1 = x − (−1), so h = −1. The outside +3 shifts up; a = −2 reflects and stretches.',plot('square',{a:-2,h:-1,k:3})),q('af-c4','Which are the zeros of y = (x − 1)² − 9?',[['pair','−2 and 4'],['vertex','1 and −9'],['wrong','−3 and 3']],'pair','Set (x − 1)² = 9. Then x − 1 = ±3, so x = −2 or 4.',plot('square',{a:1,h:1,k:-9,ymin:-10,ymax:8}))],next:'Describe a new transformed function using its vertex, axis, intercepts, and allowed inputs.'},
 {id:'trigonometry',short:'Unit circle & trigonometry',title:'How does an angle become a coordinate?',goal:'Connect radians, unit-circle coordinates, and periodic sine and cosine.',
  controls:[{name:'angle',label:'Angle θ (degrees; counterclockwise)',min:0,max:360,step:15}],defaults:{angle:45},motion:{key:'angle',end:360,replay:0},
  steps:[
   {title:'Radians measure an arc-to-radius ratio.',text:'A radian is arc length divided by radius. One full circle is 2π radians or 360°. Thus 180° = π radians and 90° = π/2. In calculus, derivative formulas for sine and cosine use radian inputs.',try:'Move to 90° and read both the degree and radian measures.'},
   {title:'Coordinates define sine and cosine.',text:'On the unit circle, the point at angle θ is (cos θ, sin θ). Cosine is the horizontal coordinate; sine is the vertical coordinate. At 90°, the point is (0, 1). A positive angle turns counterclockwise from the positive x-axis.',try:'Move to 180° and then 270°. Name the horizontal and vertical coordinates.'},
   {title:'Quadrants determine signs.',text:'In quadrant II, x is negative and y is positive, so cosine is negative and sine is positive. The radius stays 1, giving cos²θ + sin²θ = 1. A negative coordinate is a direction, not a negative radius.',try:'Move to 120°. Explain both signs from the point’s position.'},
   {title:'A full turn repeats the coordinates.',text:'Sine and cosine have period 2π radians. At θ and θ + 2π the unit-circle point is the same. Plotting the vertical coordinate against angle creates the sine curve. Amplitude, period, and shifts can later model repeating phenomena.',try:'Compare 0° and 360°. Explain why they give the same sine and cosine.'}
  ],
  predict:q('af-p3','At θ = 90° = π/2, what is (cos θ, sin θ)?',[['up','(0, 1)'],['right','(1, 0)'],['down','(0, −1)']],'up','The point is at the top of the unit circle: horizontal coordinate 0, vertical coordinate 1.',{type:'circle',angle:90}),
  checks:[q('af-c5','At θ = 180° = π, which pair is correct?',[['left','cos θ = −1; sin θ = 0.'],['swap','cos θ = 0; sin θ = −1.'],['right','cos θ = 1; sin θ = 0.']],'left','The point is (−1, 0), at the left of the unit circle.',{type:'circle',angle:180}),q('af-c6','What is sin(θ + 2π) compared with sin θ?',[['same','They are equal for every real θ.'],['negative','They always have opposite signs.'],['add','It increases by 2π.']],'same','Adding one full turn returns to the same vertical coordinate. Periodicity changes the input without adding to the output.',{type:'circle',angle:30})],next:'Convert degrees to radians, predict quadrant signs, and explain a shifted or stretched periodic model.'},
 {id:'growth',short:'Exponentials & logarithms',title:'Is the change additive or multiplicative?',goal:'Model equal-time growth with a factor and use logarithms to reverse exponentiation.',
  controls:[{name:'initial',label:'Initial amount A',min:10,max:100,step:10},{name:'factor',label:'Factor per time unit r',options:[[.5,'0.5: halve'],[1.5,'1.5: grow by 50%'],[2,'2: double']],numeric:true},{name:'t',label:'Elapsed time t',min:0,max:4,step:.25}],defaults:{initial:20,factor:2,t:1},motion:{key:'t',end:4,replay:0},
  steps:[
   {title:'Equal differences suggest a linear rule.',text:'The sequence 20, 30, 40 adds 10 each time. A linear rule is 20 + 10t. The sequence 20, 40, 80 multiplies by 2 each time. An exponential rule is 20 × 2ᵗ. Compare differences and ratios before choosing a model.',try:'Compare the exponential curve with the line matched to its initial amount and first time step.'},
   {title:'A percent change is a factor.',text:'Growth by 50% per time unit multiplies by 1 + 0.50 = 1.5. Decay by 50% multiplies by 0.5. In y = Arᵗ, A is the amount at t = 0, and r is the factor for one time unit; it is not the amount added.',try:'Set r = 1.5 and compare t = 0, 1, and 2.'},
   {title:'A logarithm asks for an exponent.',text:'logᵣ(y/A) gives the time t in y = Arᵗ, for r > 0 and r ≠ 1 and y/A > 0. For 20 × 2ᵗ = 160, we need 2ᵗ = 8, so t = log₂8 = 3. Logarithms reverse exponentiation, not multiplication.',try:'Set A = 20 and r = 2. Find the time when the amount is 160.'},
   {title:'Average change prepares for calculus.',text:'Over [u, v], the average rate is [f(v) − f(u)]/(v − u), with output units per time unit. For 20 × 2ᵗ over [0, 2], it is (80 − 20)/2 = 30. A changing average rate motivates the local-rate question in Visual Calculus; it is not yet a derivative.',try:'Compare the first-unit change with the average change over two units.'}
  ],
  predict:q('af-p4','The amount is 10, 20, 40 at times 0, 1, 2. Which rule matches?',[['exp','y = 10 × 2ᵗ'],['linear','y = 10 + 10t'],['wrong','y = 2 × 10ᵗ']],'exp','The ratios are both 2, so the amount doubles each time. The linear alternative gives 30 at t = 2.',table(['Time t','Amount'],[[0,10],[1,20],[2,40]],'Times are equally spaced.')),
  checks:[q('af-c7','An amount starts at 40 and decreases by 25% per hour. Which rule gives the amount after t hours?',[['decay','y = 40 × 0.75ᵗ'],['quarter','y = 40 × 0.25ᵗ'],['linear','y = 40 − 25t']],'decay','Each hour retains 75% of the previous amount, so the factor is 0.75.',plot('exp',{initial:40,factor:.75})),q('af-c8','Solve 3 × 2ᵗ = 24. What is t?',[['3','3'],['8','8'],['4','4']],'3','Divide by 3 to get 2ᵗ = 8. Since 2³ = 8, t = log₂8 = 3.',plot('exp',{initial:3,factor:2}))],next:'Choose linear or exponential models from new tables, check units, and reverse a growth rule with a logarithm.'}
];
const api={MODULE:'af01',TITLE:'Pre-calculus foundations',VERSION:'af01-beta-0.1',eyebrow:'PRE-CALCULUS · A BRIDGE TO VISUAL CALCULUS',headline:'Know the function.\nRead the graph.',lead:'Connect rules, inputs, graphs, angles, and growth. Build the habits you will use when studying change and accumulation.',prerequisite:'Comfortable with equations and coordinate graphs? Start here.',scope:'Selected pre-calculus foundations; wider algebra, identities, conics, sequences, and full modeling come later.',bridge:{href:'../../ad01/dist/',label:'Ready to explore change? Continue to Visual Calculus →'},LESSONS};
if(typeof module==='object'&&module.exports)module.exports=api;else root.ClueveraCourseContent=api;
})(typeof window==='undefined'?globalThis:window);
